<?php
declare(strict_types=1);require_once __DIR__.'/includes/admin_auth.php';require_once __DIR__.'/includes/csrf.php';require_once __DIR__.'/connection.php';$message='';$type='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']??'');$body=trim($_POST['message']??'');$category=trim($_POST['category']??'Announcement');$date=trim($_POST['event_date']??'');if($title===''||$body===''){$message='Title and message are required.';$type='danger';}else{$stmt=mysqli_prepare($connection,'INSERT INTO events_announcements(title,description,category,event_date,active) VALUES(?,?,?,?,1)');mysqli_stmt_bind_param($stmt,'ssss',$title,$body,$category,$date);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$message='Announcement published.';$type='success';}}$events=[];$r=mysqli_query($connection,'SELECT * FROM events_announcements ORDER BY event_date DESC,id DESC');if($r)while($row=mysqli_fetch_assoc($r))$events[]=$row;?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage Announcements | AlumTrace</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="assets/css/alumtrace.css"></head><body><?php require __DIR__.'/includes/sidebar.php';?><div class="main-wrapper"><?php require __DIR__.'/includes/topbar.php';?><main class="content"><div class="page-head"><h2>Manage Announcements</h2><p>Publish events and announcements for the alumni community.</p></div><?php if($message):?><div class="alert alert-<?=$type?>"><?=htmlspecialchars($message)?></div><?php endif;?><div class="admin-split"><div class="panel"><h2>Published content</h2><?php foreach($events as $e):?><article class="record-card"><span class="tag"><?=htmlspecialchars($e['category']??'Announcement')?></span><h3><?=htmlspecialchars($e['title'])?></h3><p><?=nl2br(htmlspecialchars($e['description']??''))?></p><small class="muted"><?=htmlspecialchars($e['event_date']??'Date not set')?></small></article><?php endforeach;?></div><div class="panel"><h2>New announcement</h2><form method="post"><?=csrf_field()?><div class="field"><label>Title</label><input class="input" name="title" required></div><div class="field"><label>Message</label><textarea class="textarea" name="message" required></textarea></div><div class="fields cols-2"><div class="field"><label>Category</label><input class="input" name="category" value="Announcement"></div><div class="field"><label>Date</label><input class="input" type="date" name="event_date"></div></div><button class="btn btn-primary" type="submit">Publish</button></form></div></div></main><?php require __DIR__.'/includes/dashboard-footer.php';?></div><script src="assets/js/alumtrace.js"></script></body></html>
